{"path": "src/App.jsx", "content": "import { useState, useEffect } from 'react';

// Pyth MCP Server integration
async function pythMCP(toolName, args) {
  try {
    // Initialize session
    const init = await fetch('https://mcp.pyth.network/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 0, method: 'initialize',
        params: { 
          protocolVersion: '2024-11-05', 
          capabilities: {}, 
          clientInfo: { name: 'dadad-game', version: '1.0' } 
        }
      })
    });
    await init.json();

    // Call the tool
    const res = await fetch('https://mcp.pyth.network/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 1, method: 'tools/call',
        params: { name: toolName, arguments: args }
      })
    });
    const data = await res.json();
    const text = data.result?.content?.[0]?.text || '';
    return JSON.parse(text);
  } catch (error) {
    console.error('Pyth MCP error:', error);
    return null;
  }
}

const ASSETS = [
  { symbol: 'Crypto.BTC/USD', name: 'Bitcoin', ticker: 'BTC' },
  { symbol: 'Crypto.ETH/USD', name: 'Ethereum', ticker: 'ETH' },
  { symbol: 'Crypto.SOL/USD', name: 'Solana', ticker: 'SOL' }
];

function App() {
  const [gameState, setGameState] = useState('start'); // start, flashing, guessing, correct, wrong, gameOver
  const [currentStreak, setCurrentStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(localStorage.getItem('dadad-best') || 0);
  const [currentAsset, setCurrentAsset] = useState(null);
  const [currentPrice, setCurrentPrice] = useState(null);
  const [choices, setChoices] = useState([]);
  const [correctChoice, setCorrectChoice] = useState(null);
  const [flashTimer, setFlashTimer] = useState(3);
  const [loading, setLoading] = useState(false);

  const formatPrice = (price) => {
    if (price >= 1000) {
      return `$${price.toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
    } else if (price >= 1) {
      return `$${price.toFixed(2)}`;
    } else {
      return `$${price.toFixed(4)}`;
    }
  };

  const generateChoices = (correctPrice) => {
    const variation = correctPrice * 0.15; // 15% variation
    const choices = [correctPrice];

    // Generate 3 wrong choices
    for (let i = 0; i < 3; i++) {
      let wrongPrice;
      do {
        const factor = 0.5 + Math.random(); // 0.5 to 1.5x variation
        wrongPrice = correctPrice + (Math.random() - 0.5) * variation * factor;
        wrongPrice = Math.max(wrongPrice, 0.01); // Minimum price
      } while (choices.some(p => Math.abs(p - wrongPrice) / wrongPrice < 0.05)); // Ensure 5% difference

      choices.push(wrongPrice);
    }

    return choices.sort(() => Math.random() - 0.5);
  };

  const startNewRound = async () => {
    setLoading(true);
    const asset = ASSETS[Math.floor(Math.random() * ASSETS.length)];

    try {
      // Get current price from Pyth MCP
      const priceData = await pythMCP('get_symbols', { 
        query: asset.ticker.toLowerCase(), 
        limit: 1 
      });

      if (!priceData || !priceData[0]) {
        throw new Error('Failed to fetch price data');
      }

      const price = priceData[0].price;
      const choices = generateChoices(price);
      const correctIndex = choices.findIndex(p => p === price);

      setCurrentAsset(asset);
      setCurrentPrice(price);
      setChoices(choices);
      setCorrectChoice(correctIndex);
      setGameState('flashing');
      setFlashTimer(3);
      setLoading(false);

      // Flash timer countdown
      const timer = setInterval(() => {
        setFlashTimer(prev => {
          if (prev <= 1) {
            clearInterval(timer);
            setGameState('guessing');
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } catch (error) {
      console.error('Error starting round:', error);
      setLoading(false);
      // Use fallback mock data if Pyth MCP fails
      const mockPrices = { BTC: 67234, ETH: 3456, SOL: 145 };
      const price = mockPrices[asset.ticker];
      const choices = generateChoices(price);

      setCurrentAsset(asset);
      setCurrentPrice(price);
      setChoices(choices);
      setCorrectChoice(0); // First choice is correct in mock
      setGameState('flashing');
      setFlashTimer(3);

      const timer = setInterval(() => {
        setFlashTimer(prev => {
          if (prev <= 1) {
            clearInterval(timer);
            setGameState('guessing');
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
  };

  const handleChoice = (choiceIndex) => {
    const isCorrect = choiceIndex === correctChoice;

    if (isCorrect) {
      setGameState('correct');
      const newStreak = currentStreak + 1;
      setCurrentStreak(newStreak);

      if (newStreak > bestStreak) {
        setBestStreak(newStreak);
        localStorage.setItem('dadad-best', newStreak);
      }

      setTimeout(() => startNewRound(), 1500);
    } else {
      setGameState('wrong');
      setTimeout(() => {
        setGameState('gameOver');
      }, 2000);
    }
  };

  const startGame = () => {
    setCurrentStreak(0);
    startNewRound();
  };

  const resetGame = () => {
    setGameState('start');
    setCurrentStreak(0);
    setCurrentAsset(null);
    setCurrentPrice(null);
    setChoices([]);
  };

  return (
    <div className="game-container">
      <h1 className="title">DADAD</h1>

      <div className="stats">
        <div className="stat">
          <div className="stat-label">Current Streak</div>
          <div className="stat-value">{currentStreak}</div>
        </div>
        <div className="stat">
          <div className="stat-label">Best Streak</div>
          <div className="stat-value">{bestStreak}</div>
        </div>
      </div>

      {gameState === 'start' && (
        <div>
          <p style={{ marginBottom: '2rem', fontSize: '1.1rem', opacity: 0.8 }}>
            Remember the crypto price, then pick it from the choices!
          </p>
          <button className="start-btn" onClick={startGame}>
            Start Game
          </button>
        </div>
      )}

      {loading && (
        <div className="loading">
          Loading live crypto prices...
        </div>
      )}

      {(gameState === 'flashing' || gameState === 'correct' || gameState === 'wrong') && currentAsset && (
        <div className="flash-card">
          <div className="asset-name">{currentAsset.name} ({currentAsset.ticker})</div>
          <div className="price-display">{formatPrice(currentPrice)}</div>
          {gameState === 'flashing' && (
            <div className="timer">{flashTimer}s</div>
          )}
          {gameState === 'correct' && (
            <div style={{ color: '#00ff88', fontSize: '1.2rem', fontWeight: 'bold' }}>
              Correct! 🎉
            </div>
          )}
          {gameState === 'wrong' && (
            <div style={{ color: '#ff3030', fontSize: '1.2rem', fontWeight: 'bold' }}>
              Wrong! 💥
            </div>
          )}
        </div>
      )}

      {gameState === 'guessing' && (
        <div>
          <div className="flash-card" style={{ opacity: 0.3 }}>
            <div className="asset-name">{currentAsset.name} ({currentAsset.ticker})</div>
            <div className="price-display">???</div>
          </div>

          <div className="choices">
            {choices.map((choice, index) => (
              <button
                key={index}
                className="choice-btn"
                onClick={() => handleChoice(index)}
              >
                {formatPrice(choice)}
              </button>
            ))}
          </div>
        </div>
      )}

      {gameState === 'gameOver' && (
        <div className="game-over">
          <h2>Game Over!</h2>
          <div className="final-score">
            Streak: {currentStreak}
          </div>
          <p style={{ marginBottom: '2rem', opacity: 0.8 }}>
            {currentStreak === bestStreak && currentStreak > 0 ? "New record! 🏆" : "Try again!"}
          </p>
          <button className="start-btn" onClick={resetGame}>
            Play Again
          </button>
        </div>
      )}
    </div>
  );
}

export default App;"}

