}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: white;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

#root {
  width: 100%;
  max-width: 500px;
  padding: 20px;
}

.game-container {
  text-align: center;
}

.title {
  font-size: 3rem;
  font-weight: bold;
  background: linear-gradient(45deg, #00d4ff, #ff6b00);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 2rem;
}

.stats {
  display: flex;
  justify-content: space-between;
  margin-bottom: 2rem;
  padding: 1rem;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  backdrop-filter: blur(10px);
}

.stat {
  text-align: center;
}

.stat-label {
  font-size: 0.9rem;
  opacity: 0.7;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: bold;
  color: #00d4ff;
}

.flash-card {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 3rem;
  margin: 2rem 0;
  backdrop-filter: blur(10px);
  border: 2px solid rgba(255, 255, 255, 0.2);
}

.price-display {
  font-size: 2.5rem;
  font-weight: bold;
  color: #00ff88;
  margin-bottom: 1rem;
}

.asset-name {
  font-size: 1.2rem;
  opacity: 0.8;
  margin-bottom: 0.5rem;
}

.timer {
  font-size: 1rem;
